PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
import ast,hashlib,json,pathlib,subprocess
baseline='8f61ae5f68c0846d5149aceb4df55c69263c9df2'
application='e97be5bd8fb0b0c04f44592a9ba218cda9934f05'
def paths(commit,*names):
 return subprocess.check_output(['git','ls-tree','-r','--name-only',commit,'--',*names]).decode().splitlines()
def sha(raw): return hashlib.sha256(raw).hexdigest()
def audit(commit,names):
 rows={}
 for name in names:
  expected=subprocess.check_output(['git','show',commit+':'+name]); actual=pathlib.Path(name).read_bytes()
  rows[name]={'sha256':sha(actual),'baseline_sha256':sha(expected),'byte_exact':actual==expected}
 return rows
sources=paths(baseline,'src','pyproject.toml')
actual_sources=set(subprocess.check_output(['rg','--files','src']).decode().splitlines())|{'pyproject.toml'}
afiles=paths(application,'examples/acceptance')+['tests/test_acceptance_compression.py','tests/test_acceptance_policy_review.py','tests/test_acceptance_product.py','tests/test_acceptance_sorting.py']
source_rows=audit(baseline,sources); application_rows=audit(application,afiles)
testpath=pathlib.Path('tests/test_holdout_domain_review.py'); testtree=ast.parse(testpath.read_bytes()); asserts=[ast.dump(n,include_attributes=False) for n in ast.walk(testtree) if isinstance(n,ast.Assert)]
result={'core_baseline':baseline,'application_baseline':application,'source_and_build_count':len(sources),'source_manifest_sha256':sha(json.dumps(source_rows,sort_keys=True,separators=(',',':')).encode()),'source_mismatches':[name for name,row in source_rows.items() if not row['byte_exact']],'source_added':sorted(actual_sources-set(sources)),'source_removed':sorted(set(sources)-actual_sources),'application_count':len(afiles),'application_files':application_rows,'test_sha256':sha(testpath.read_bytes()),'literal_assert_count':len(asserts),'assert_ast_sha256':sha(json.dumps(asserts,ensure_ascii=False,separators=(',',':')).encode()),'test_ast_sha256':sha(ast.dump(testtree,include_attributes=False).encode())}
assert len(afiles)==11 and len(sources)==278
assert not result['source_mismatches'] and not result['source_added'] and not result['source_removed']
assert all(row['byte_exact'] for row in application_rows.values())
print(json.dumps(result,sort_keys=True,indent=2))
